<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="page-heading"><div><p class="eyebrow">Inventory</p><h1>Products</h1></div><a class="button" href="<?= site_url('products/new') ?>">New Product</a></div><div class="card-grid"><?php foreach($products as $p): ?><article class="product-card"><img src="<?= base_url($p['image']?'uploads/'.rawurlencode($p['image']):'images/product-placeholder.svg') ?>" alt=""><div><h2><?= esc($p['name']) ?></h2><p class="price">₱<?= number_format((float)$p['price'],2) ?></p><p>Stock: <?= esc($p['stock_quantity']) ?></p><div class="row-actions"><a class="text-link" href="<?= site_url('products/'.$p['id'].'/edit') ?>">Edit</a><form action="<?= site_url('products/'.$p['id'].'/delete') ?>" method="post" onsubmit="return confirm('Delete this product?')"><?= csrf_field() ?><button class="danger-link">Delete</button></form></div></div></article><?php endforeach; ?><?php if(!$products): ?><p>No products found.</p><?php endif; ?></div><?= $this->endSection() ?>
